/**
 * Retro interface sounds generated by code (ZzFX, MIT): no audio files.
 *
 * Rules (ADR 0010/0012): nothing plays before the first user interaction
 * (browser autoplay policy), the mute choice is remembered on the device and
 * the synth is loaded on demand, outside the initial bundle.
 */

export type SoundName =
  'click' | 'confirm' | 'error' | 'whistle' | 'crowd' | 'coin' | 'goal';

/** ZzFX parameter lists (volume, randomness, frequency, attack, ...). */
const SOUNDS: Readonly<Record<SoundName, readonly (number | undefined)[]>> = {
  click: [0.4, , 420, , 0.01, 0.03, , 1.6, , , , , , , , , , 0.6, 0.01],
  confirm: [0.5, , 523, 0.01, 0.08, 0.14, , 1.4, , , 196, 0.06, , , , , , 0.7],
  error: [0.5, , 160, 0.01, 0.08, 0.18, 2, 1.1, , , , , , 0.3, , , , 0.6],
  whistle: [0.5, , 2200, 0.02, 0.18, 0.08, , 1.8, , , , , 0.08, , , , , 0.5],
  crowd: [0.35, 0.4, 90, 0.2, 0.5, 0.9, 4, 0.3, , , , , , 1.6, , 0.1, , 0.4],
  coin: [0.45, , 1046, , 0.04, 0.16, , 1.6, , , 523, 0.05, , , , , , 0.7],
  goal: [0.55, , 392, 0.02, 0.12, 0.3, , 1.5, , , 262, 0.08, 0.05, , , , , 0.8],
};

export const MUTE_STORAGE_KEY = 'footebas:retro-muted';

type Listener = (muted: boolean) => void;

const listeners = new Set<Listener>();
let muted: boolean | null = null;
let unlocked = false;
let armed = false;
let synth: ((...parameters: (number | undefined)[]) => unknown) | null = null;

function storage(): Storage | null {
  try {
    return globalThis.localStorage ?? null;
  } catch {
    return null;
  }
}

/** Whether sounds are muted; read once from the device, default on. */
export function isMuted(): boolean {
  if (muted === null) muted = storage()?.getItem(MUTE_STORAGE_KEY) === '1';
  return muted;
}

export function setMuted(value: boolean): void {
  muted = value;
  try {
    storage()?.setItem(MUTE_STORAGE_KEY, value ? '1' : '0');
  } catch {
    // Private mode or blocked storage: the choice lasts for the session.
  }
  for (const listener of listeners) listener(value);
}

export function toggleMuted(): boolean {
  setMuted(!isMuted());
  return isMuted();
}

export function subscribeMuted(listener: Listener): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** True once the user has interacted with the page. */
export function isUnlocked(): boolean {
  return unlocked;
}

/** Marks the first interaction; from here on `play` is allowed. */
export function unlock(): void {
  unlocked = true;
}

/**
 * Listens for the first pointer or key interaction on the document and
 * unlocks audio. Safe to call many times; a no-op without a DOM.
 */
export function armSoundUnlock(): () => void {
  if (armed || typeof document === 'undefined') return () => undefined;
  armed = true;
  const once = () => {
    unlock();
    document.removeEventListener('pointerdown', once);
    document.removeEventListener('keydown', once);
    armed = false;
  };
  document.addEventListener('pointerdown', once, { passive: true });
  document.addEventListener('keydown', once);
  return once;
}

/**
 * Plays an interface sound when allowed (unlocked and not muted). Returns a
 * promise that resolves to whether the sound was requested from the synth.
 */
export async function play(name: SoundName): Promise<boolean> {
  if (!unlocked || isMuted()) return false;
  if (!synth) {
    try {
      const loaded = await import('zzfx');
      synth = loaded.zzfx;
    } catch {
      return false;
    }
  }
  try {
    synth(...SOUNDS[name]);
    return true;
  } catch {
    return false;
  }
}

/** Test seam: forgets the cached state (mute, unlock, synth). */
export function resetSoundForTests(
  fake?: (...parameters: (number | undefined)[]) => unknown,
): void {
  muted = null;
  unlocked = false;
  armed = false;
  synth = fake ?? null;
  listeners.clear();
}
